pub struct BlockRequestBuilder<'a: 'b, 'b> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b> BlockRequestBuilder<'a, 'b> {
  #[inline]
  pub fn add_version(&mut self, version: u16) {
    self.fbb_.push_slot::<u16>(BlockRequest::VT_VERSION, version, 1);
  }
  #[inline]
  pub fn add_credential_type(&mut self, credential_type: Credential) {
    self.fbb_.push_slot::<Credential>(BlockRequest::VT_CREDENTIAL_TYPE, credential_type, Credential::NONE);
  }
  #[inline]
  pub fn add_credential(&mut self, credential: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(BlockRequest::VT_CREDENTIAL, credential);
  }
  #[inline]
  pub fn add_body_type(&mut self, body_type: RequestBody) {
    self.fbb_.push_slot::<RequestBody>(BlockRequest::VT_BODY_TYPE, body_type, RequestBody::NONE);
  }
  #[inline]
  pub fn add_body(&mut self, body: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(BlockRequest::VT_BODY, body);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>) -> BlockRequestBuilder<'a, 'b> {
    let start = _fbb.start_table();
    BlockRequestBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<BlockRequest<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

